The violated invariant is uniform participation in the block-wide barrier. With valid equal to 70, threads 0–69 reach __syncthreads() while threads 70–95 skip it; that is undefined behavior, not a guarantee that every device hangs. Immediate launch checks detect launch errors, not successful kernel completion, and a responsive host endpoint does not establish GPU progress.

Guard the loads, but execute the barrier unconditionally:

```cuda
// sum.cu
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

#define CHECK(call) do {                                      \
    cudaError_t e = (call);                                    \
    if (e != cudaSuccess) {                                   \
        std::fprintf(stderr, "%s: %s\n", #call,                \
                     cudaGetErrorString(e));                  \
        std::exit(EXIT_FAILURE);                              \
    }                                                         \
} while (0)

__global__ void sum_valid(const float* input, float* output,
                          int valid) {
    __shared__ float values[96];
    const int tid = threadIdx.x;

    if (tid < valid) {
        values[tid] = input[tid];
    }
    __syncthreads();

    if (tid == 0) {
        float sum = 0.0f;
        for (int i = 0; i < valid; ++i) {
            sum += values[i];
        }
        output[0] = sum;
    }
}

int main(int argc, char** argv) {
    int valid = 70;
    if (argc > 2) {
        std::fprintf(stderr, "Usage: %s [valid: 0..96]\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (argc == 2) {
        char* end = nullptr;
        long n = std::strtol(argv[1], &end, 10);
        if (end == argv[1] || *end != '\0' || n < 0 || n > 96) {
            std::fprintf(stderr, "valid must be an integer in 0..96\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<int>(n);
    }

    float input[96];
    for (int i = 0; i < 96; ++i) input[i] = 1.0f;
    float output = -1.0f;
    float *device_input = nullptr, *device_output = nullptr;
    cudaStream_t stream;
    cudaEvent_t done;

    CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    CHECK(cudaEventCreateWithFlags(&done, cudaEventDisableTiming));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_input),
                     sizeof(input)));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_output),
                     sizeof(output)));
    CHECK(cudaMemcpyAsync(device_input, input, sizeof(input),
                          cudaMemcpyHostToDevice, stream));

    sum_valid<<<1, 96, 0, stream>>>(device_input, device_output, valid);
    CHECK(cudaGetLastError());
    CHECK(cudaMemcpyAsync(&output, device_output, sizeof(output),
                          cudaMemcpyDeviceToHost, stream));
    CHECK(cudaEventRecord(done, stream));
    CHECK(cudaEventSynchronize(done));

    std::printf("valid=%d, sum=%.0f\n", valid, output);
    CHECK(cudaFree(device_output));
    CHECK(cudaFree(device_input));
    CHECK(cudaEventDestroy(done));
    CHECK(cudaStreamDestroy(stream));
    return EXIT_SUCCESS;
}
```

Compile with `nvcc sum.cu -o sum`, using the CUDA toolkit and a supported GPU. Run `./sum 70`; the argument can be any integer from 0 through 96. The kernel requires exactly one block of 96 threads and the allocated buffers shown above.

Synchronization and bounds proof:
1. Every thread has tid in 0–95. A load occurs only when tid < valid, so every input and shared-memory access during loading is within bounds.
2. Every thread reaches the same unconditional barrier exactly once, with no early return. The barrier makes all preceding shared-memory writes visible to thread zero before its reads.
3. Thread zero reads only indices 0 through valid−1. Each such entry was written by the corresponding thread before the barrier; unused shared entries are never read. Only thread zero writes output[0], so there is no competing writer.
4. At valid=0, no inputs or shared entries are read, and output is explicitly zero. At valid=96, indices 0–95 are initialized and summed. For the demonstrated all-ones input, the output is exactly valid.
5. The input copy, kernel, output copy, and event are ordered in the same stream. Successful event synchronization establishes completion before the host reads output or releases the buffers.
